import{z as s,x as n,o as l,c as o,q as r,j as E,D as a,d as c,s as A,S as d}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"reduce-scatter 与 all-gather","description":"","frontmatter":{"title":"reduce-scatter 与 all-gather","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/reduce-scatter-allgather.md","filePath":"llm/reduce-scatter-allgather.md","lastUpdated":1791413859000}'),u={name:"llm/reduce-scatter-allgather.md"};function i(p,e,B,h,g,R){const t=n("Mermaid");return l(),o("div",null,[e[2]||(e[2]=r('<h1 id="reduce-scatter-与-all-gather" tabindex="-1">reduce-scatter 与 all-gather <a class="header-anchor" href="#reduce-scatter-与-all-gather" aria-label="Permalink to &quot;reduce-scatter 与 all-gather&quot;">​</a></h1><div class="epigraph"><p>All-Reduce 不是原子：它是一次把和摊到各卡的 reduce-scatter，加上一次把各片收回来的 all-gather。ZeRO 把中间那一份「全量副本」删掉，于是这两步单独露面。</p><footer>—— 对照 MPI 集合原语与 DeepSpeed ZeRO 对梯度 / 参数分片的用法</footer></div><p><a href="/llm/ring-tree-allreduce">上一课</a> 把 All-Reduce 写成环上的两阶段。本课把两阶段升格为<strong>一等原语</strong>：reduce-scatter 与 all-gather。缺口不是再讲一遍环怎么转，而是 <a href="/llm/data-parallel-zero">数据并行与 ZeRO</a> 为什么不再调用 All-Reduce：它只需要「每卡持有归约后的一片」和「每卡在前向之前拿回自己要用的参数片」。后课 all-to-all 是置换，不是归约；本课先把可加集合的一对原语讲清。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>All-Reduce 的语义是每卡得到<strong>完整</strong>的和。若下一步立刻用完整梯度做 Adam，这个语义是对的。ZeRO 把优化器状态按参数下标切走之后，第 \\(r\\) 张卡只拥有第 \\(r\\) 片：它只需要那一片的平均梯度，不需要别人那一片。若仍做 All-Reduce，等于先凑齐再扔掉 \\(\\frac{N-1}{N}\\)，带宽白付。</p><p><span class="marginnote">代入几个数感受一下：\\(N=8\\) 卡、每卡梯度 4 GB 时，All-Reduce 每卡约要搬 \\(4 \\times \\frac{7}{8} \\times 2 = 7\\) GB（归约与分发各一段）；只做 reduce-scatter，每卡搬约 3.5 GB 就拿到自己那一片。省下的那一半，正是 ZeRO 根本不需要的那份全量副本。</span></p><p>对称地，前向需要完整权重时，并不是「从根广播一份」，而是各卡已经持有自己那一片，做一次 all-gather 就能拼回。张量并行的列切 / 行切，也是同一对：先局部 GEMM，再 all-gather 激活或 reduce-scatter 梯度，而不是每次都 All-Reduce 完整隐藏态。问题是：<strong>什么时候必须看到全量，什么时候一片就够</strong>。</p><p><span class="marginnote">MPI 把 <code>MPI_Reduce_scatter</code> 与 <code>MPI_Allgather</code> 写成独立调用。NCCL 同样暴露 <code>ncclReduceScatter</code> 与 <code>ncclAllGather</code>。训练框架若只封装 All-Reduce，ZeRO-2/3 与 Megatron 的序列并行会被迫多搬一倍字节。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>Reduce-scatter：输入每卡一份长度为 \\(n\\) 的向量，输出每卡一份长度为 \\(n/N\\) 的归约结果，第 \\(r\\) 卡得到全局和下标区间 \\(I_r\\)。通信量下界约为每卡 \\(\\frac{N-1}{N}n\\)，与 All-Reduce 的一半同阶——因为 All-Reduce ≈ reduce-scatter + all-gather，两段各一半。</p><p>All-gather：输入每卡一份 \\(n/N\\)，输出每卡一份拼接后的 \\(n\\)。没有加法，只搬数据。通信量同样约 \\(\\frac{N-1}{N}n\\)。实现仍可以是环（每步把当前片转给邻居）或树（先集中再展开），选择逻辑与上一课相同：大消息环，小消息树。</p>',11)),(l(),E(d,null,{default:a(()=>[A(t,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20LR%0A%20%20G%5B%22%E6%AF%8F%E5%8D%A1%E5%85%A8%E9%87%8F%E6%A2%AF%E5%BA%A6%22%5D%20--%3E%20RS%5B%22reduce-scatter%22%5D%0A%20%20RS%20--%3E%20S%5B%22%E6%AF%8F%E5%8D%A1%201%2FN%20%E5%BD%92%E7%BA%A6%E7%89%87%22%5D%0A%20%20S%20--%3E%20AG%5B%22all-gather%22%5D%0A%20%20AG%20--%3E%20AR%5B%22%E6%AF%8F%E5%8D%A1%E5%85%A8%E9%87%8F%E5%92%8C%20%3D%20All-Reduce%22%5D%0A%20%20S%20--%3E%20Z%5B%22ZeRO%3A%20%E5%8F%AA%E5%AF%B9%E6%8C%81%E6%9C%89%E7%89%87%E5%81%9A%20Adam%22%5D%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[c(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=r('<p><a href="/llm/tensor-parallel">张量并行</a> 里，列并行的输出 all-gather、行并行的输入 all-gather，以及反向对应的 reduce-scatter，就是把这一对原语钉在层边界上。不要把它们再包装成层内 All-Reduce，除非实现真的需要每卡一份完整激活。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>环上的 reduce-scatter 与 all-gather 可以共用同一套 chunk 调度，只是本地操作不同：前者邻居数据要加进本地片，后者只覆盖或拼接。NCCL 因此能把一次 All-Reduce 做成两次集体调用的融合核，也可以让框架拆开，在中间插入「只更新本片优化器」。拆开之后，计算–通信重叠的窗口变了：reduce-scatter 可以在反向后几层还在算时发出；all-gather 必须在下一微批前向用到该片之前完成。ZeRO-3 的参数 all-gather 因此更容易撞上关键路径，这是分片换来的通信形状，不是网卡变慢。</p><p><span class="marginnote">计算–通信重叠可以类比成「一边炒下一道菜、一边把上一道装盘外送」：reduce-scatter 趁反向还没全部算完就能提前发出，通信藏在计算里；而 all-gather 像开火前必须备齐的食材，晚到一秒前向就得干等——这就是 ZeRO-3 更容易撞关键路径的直觉。</span></p><p><span class="marginnote">反过来看一个正面例子：若反向只剩最后两层、通信要搬 3.5 GB 而网卡每秒跑 25 GB，RS 大约 0.14 秒就能完成——只要前几层的计算超过这个时长，通信就完全被「盖住」，训练不慢半拍。重叠窗口够大，分片的通信代价就接近免费。</span></p>',5)),(l(),E(d,null,{default:a(()=>[A(t,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20B1%5B%22%E5%8F%8D%E5%90%91%E6%9C%80%E5%90%8E%E5%87%A0%E5%B1%82%E7%AE%97%E5%AE%8C%22%5D%20--%3E%20RS%5B%22%E7%AB%8B%E5%8D%B3%E5%8F%91%E5%87%BA%20reduce-scatter%20%E6%A2%AF%E5%BA%A6%E7%89%87%22%5D%0A%20%20RS%20--%3E%20OVL%5B%22%E4%B8%8E%E5%89%8D%E9%9D%A2%E5%B1%82%E7%9A%84%E5%8F%8D%E5%90%91%E8%AE%A1%E7%AE%97%E9%87%8D%E5%8F%A0%2C%20%E4%B8%8D%E5%8D%A0%E5%85%B3%E9%94%AE%E8%B7%AF%E5%BE%84%22%5D%0A%20%20OVL%20--%3E%20OPT%5B%22%E6%AF%8F%E5%8D%A1%E5%8F%AA%E5%AF%B9%E8%87%AA%E5%B7%B1%E9%82%A3%E4%B8%80%E7%89%87%E8%B7%91%20Adam%22%5D%0A%20%20OPT%20--%3E%20AGW%5B%22ZeRO-3%3A%20%E4%B8%8B%E4%B8%80%E5%BE%AE%E6%89%B9%E5%89%8D%E5%90%91%E5%89%8D%20all-gather%20%E5%8F%82%E6%95%B0%E7%89%87%22%5D%0A%20%20AGW%20--%3E%20CP%5B%22all-gather%20%E5%9C%A8%E5%85%B3%E9%94%AE%E8%B7%AF%E5%BE%84%E4%B8%8A%2C%20%E5%BB%B6%E8%BF%9F%E7%9B%B4%E6%8E%A5%E6%8B%96%E6%85%A2%E8%AE%AD%E7%BB%83%22%5D%0A%20%20CP%20--%3E%20GEMM%5B%22%E6%8B%BC%E5%9B%9E%E5%85%A8%E9%87%8F%E6%9D%83%E9%87%8D%2C%20%E8%BF%9B%E5%85%A5%E5%89%8D%E5%90%91%20GEMM%22%5D%0A"})]),fallback:a(()=>[...e[1]||(e[1]=[c(" Loading... ",-1)])]),_:1})),e[4]||(e[4]=r('<p>数据量上，一对 RS+AG 与一次 AR 搬的字节同阶。省的不是「少一次集体」，而是 <strong>省掉全量副本的显存</strong>，以及在「不需要全量」时只做一半。若框架误把 ZeRO 写成「All-Reduce 后再切片」，通信回到 DDP，显存却按 ZeRO 宣传——这是配置事故。</p><p><span class="marginnote">序列并行 / 上下文并行常对激活做 all-gather 或 reduce-scatter，体积跟序列长度走，与梯度 All-Reduce 的「每步一次参数量」不是同一条屋顶线。并行维正交：不要把 CP 的激活集体算进 DP 的梯度预算。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>片必须整除，或至少在通信库里可填充。隐藏维、专家数、词表切分若不能被 TP/DP 度整除，会多出不均片，环的负载不再对称。In-network 归约通常针对 All-Reduce 语义；拆成 RS+AG 之后，交换机侧未必有同样的卸载，带宽模型要按主机侧集体重测。</p><p>All-gather 没有归约，不能靠「先节点内加再跨节点」减体积——层次化只能减控制开销，不能减数据。这与下一课 all-to-all 同类：不可加的数据必须真正送到对端。能加的才配 reduce-scatter。</p><p><span class="marginnote">初学者容易以为「节点内先聚一下、再上跨节点」能省任何集体通信的量。这对可加的 All-Reduce 大体成立（节点内先加成一份再送出去）；但 all-gather 没有加法可做，每个字节最终都要原样送达对端，层次化只省一点握手开销，省不了数据体积。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Reduce-scatter 给出每卡一片归约结果；all-gather 把各片拼回全量。</li><li>All-Reduce 在通信量上约等于二者串联；ZeRO 与 TP 常常只需要其中一步。</li><li>省的是全量副本与「不需要全量时的那一半」，不是魔法减字节。</li><li>All-gather 不可加，层次化减不了数据体积。</li><li>出处：MPI / NCCL 原语；ZeRO 与 Megatron 类切分对二者的直接调用。</li></ul>',8))])}const _=s(u,[["render",i]]);export{D as __pageData,_ as default};
